    const pages = window.MOTIVATE_PAGES.filter(function (p) { return p.id !== '0'; });
    const last = pages.length;
    const $ = function (id) { return document.getElementById(id); };
    const form = $('builderForm');
    const tbody = $('lineRows');
    const statusEl = $('status');
    const online = location.protocol === 'http:';
    const params = new URLSearchParams(location.search);

    let busy = false;
    let dirty = false;
    let loadedNumber = null;     // edit mode: page currently in the form

    function mode() { return form.querySelector('input[name="mode"]:checked').value; }

    // ---------- Line rows (add / delete) ----------
    function options(list) {
        return list.map(function (v) { return '<option>' + v + '</option>'; }).join('');
    }

    function makeRow(line) {
        const tr = document.createElement('tr');
        tr.innerHTML =
            '<td></td>' +
            '<td class="text-cell"><input class="text" type="text" maxlength="500"></td>' +
            '<td><select class="font">' + options(FONTS) + '</select></td>' +
            '<td><input class="size" type="number" min="0.5" max="20" step="0.1"></td>' +
            '<td><select class="font_type">' + options(TYPES) + '</select></td>' +
            '<td><input class="color" type="color" list="palette"></td>' +
            '<td><input class="space_after" type="number" min="0" max="20" step="0.1"></td>' +
            '<td><button type="button" class="icon-btn add" title="Add a line below">+</button> ' +
            '<button type="button" class="icon-btn delete" title="Delete this line">&times;</button></td>';
        setLine(tr, line);
        return tr;
    }

    function setLine(tr, line) {
        const full = Object.assign({}, LINE_DEFAULT, line || {});
        Object.keys(LINE_DEFAULT).forEach(function (k) {
            tr.querySelector('.' + k).value = full[k];
        });
    }

    function getLine(tr) {
        const line = {};
        Object.keys(LINE_DEFAULT).forEach(function (k) {
            line[k] = tr.querySelector('.' + k).value;
        });
        return line;
    }

    function rows() { return Array.prototype.slice.call(tbody.rows); }

    // A new line copies the style of the line above it, with empty text.
    function styleFrom(tr) {
        return tr ? Object.assign(getLine(tr), { text: '' }) : null;
    }

    function addLine(afterRow) {
        if (rows().length >= MAX_LINES) return;
        const ref = afterRow || tbody.lastElementChild;
        const tr = makeRow(styleFrom(ref));
        tbody.insertBefore(tr, ref ? ref.nextSibling : null);
        renumberRows();
        tr.querySelector('.text').focus();
        changed();
    }

    function deleteLine(tr) {
        if (rows().length <= 1) return;
        const text = tr.querySelector('.text').value.trim();
        if (text && !confirm('Delete line ' + tr.cells[0].textContent + '?\n\n' + text)) return;
        const next = tr.nextElementSibling || tr.previousElementSibling;
        tr.remove();
        renumberRows();
        if (next) next.querySelector('.text').focus();
        changed();
    }

    function renumberRows() {
        const all = rows();
        all.forEach(function (tr, i) {
            const n = i + 1;
            tr.cells[0].textContent = n;
            [['text', 'text'], ['font', 'font'], ['size', 'font size'], ['font_type', 'font type'],
             ['color', 'font color'], ['space_after', 'spacing after']].forEach(function (pair) {
                tr.querySelector('.' + pair[0]).setAttribute('aria-label', 'Line ' + n + ' ' + pair[1]);
            });
            tr.querySelector('.add').setAttribute('aria-label', 'Add a line below line ' + n);
            tr.querySelector('.delete').setAttribute('aria-label', 'Delete line ' + n);
            tr.querySelector('.add').disabled = all.length >= MAX_LINES;
            tr.querySelector('.delete').disabled = all.length <= 1;
        });
        $('addLineBtn').disabled = all.length >= MAX_LINES;
        $('lineCount').textContent = all.length + ' of ' + MAX_LINES + ' lines';
    }

    function setLines(lines) {
        tbody.innerHTML = '';
        const list = lines && lines.length ? lines.slice(0, MAX_LINES) : [];
        while (list.length < (lines && lines.length ? 0 : START_LINES)) list.push(null);
        list.forEach(function (line) { tbody.appendChild(makeRow(line)); });
        renumberRows();
    }

    tbody.addEventListener('click', function (e) {
        const b = e.target.closest('button');
        if (!b) return;
        const tr = b.closest('tr');
        if (b.classList.contains('add')) addLine(tr);
        else if (b.classList.contains('delete')) deleteLine(tr);
    });
    $('addLineBtn').addEventListener('click', function () { addLine(null); });

    // ---------- Read / write the form ----------
    function getSpec() {
        return {
            number: $('pageNumber').value,
            name: $('pageName').value,
            h_align: $('hAlign').value,
            h_indent: $('hIndent').value,
            v_align: $('vAlign').value,
            v_indent: $('vIndent').value,
            lines: rows().map(getLine)
        };
    }

    function setSpec(spec) {
        $('pageNumber').value = spec.number;
        $('pageName').value = spec.name || '';
        $('hAlign').value = spec.h_align || 'Center';
        $('hIndent').value = spec.h_indent || 0;
        $('vAlign').value = spec.v_align || 'Middle';
        $('vIndent').value = spec.v_indent || 0;
        setLines(spec.lines);
        dirty = false;
        refresh();
    }

    function cameFrom() {
        const at = parseInt(params.get('at'), 10);
        return at >= 1 && at <= last + 1 ? at : last + 1;
    }

    function refresh() {
        const editing = mode() === 'edit';
        const k = parseInt($('pageNumber').value, 10);
        const top = editing ? last : last + 1;
        $('pageNumber').max = top;
        $('numberLabel').textContent = editing ? 'Page to Edit' : 'Page Number';
        $('loadBtn').hidden = !editing;
        $('saveBtn').textContent = editing ? 'SAVE' : 'CREATE';
        $('hIndent').disabled = $('hAlign').value === 'Center';
        $('vIndent').disabled = $('vAlign').value === 'Middle';

        const hint = $('numberHint');
        if (!(k >= 1 && k <= top)) {
            hint.textContent = 'Choose 1 to ' + top;
        } else if (editing) {
            hint.textContent = loadedNumber === k
                ? 'Editing ' + k + ' - ' + pages[k - 1].label.toUpperCase()
                : 'Click LOAD to edit ' + k + ' - ' + pages[k - 1].label.toUpperCase();
        } else if (k === last + 1) {
            hint.textContent = 'Added at the end (after ' + last + ' - ' + pages[last - 1].label.toUpperCase() + ')';
        } else {
            hint.textContent = 'Inserted before ' + k + ' - ' + pages[k - 1].label.toUpperCase() +
                '; pages ' + k + '-' + last + ' become ' + (k + 1) + '-' + (last + 1);
        }
        const ready = online && !busy;
        $('loadBtn').disabled = !ready;
        $('previewBtn').disabled = !ready || (editing && loadedNumber === null);
        $('saveBtn').disabled = !ready || (editing && loadedNumber !== k);
    }

    function changed() {
        dirty = true;
        refresh();
        if (mode() === 'new') saveDraft();
    }

    function saveDraft() {
        try { localStorage.setItem(DRAFT_KEY, JSON.stringify(getSpec())); } catch (e) { /* storage unavailable */ }
    }

    function loadDraft() {
        try { return JSON.parse(localStorage.getItem(DRAFT_KEY) || 'null'); } catch (e) { return null; }
    }

    function clearDraft() {
        try { localStorage.removeItem(DRAFT_KEY); } catch (e) { /* storage unavailable */ }
    }

    function setStatus(text, isError) {
        statusEl.textContent = text;
        statusEl.classList.toggle('error', !!isError);
    }

    function setBusy(value) {
        busy = value;
        refresh();
    }

    // ---------- Server calls ----------
    function post(action, spec) {
        return fetch('/api/' + action, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(spec)
        }).then(function (r) { return r.json(); });
    }

    function loadPage(k) {
        if (dirty && loadedNumber !== null && !confirm('Discard your changes to page ' + loadedNumber + '?')) return;
        setBusy(true);
        setStatus('Loading page ' + k + '...');
        fetch('/api/page?n=' + encodeURIComponent(k), { cache: 'no-store' })
            .then(function (r) { return r.json(); })
            .then(function (res) {
                if (!res.ok) throw new Error(res.error);
                loadedNumber = res.spec.number;
                setSpec(res.spec);
                setStatus('Loaded ' + k + ' - ' + res.spec.name.toUpperCase() + ' (' + res.spec.lines.length + ' lines)');
            })
            .catch(function (err) { setStatus(err.message || 'Load failed', true); })
            .finally(function () { setBusy(false); });
    }

    function preview() {
        setBusy(true);
        setStatus('Building preview...');
        post('preview', getSpec()).then(function (res) {
            if (!res.ok) throw new Error(res.error);
            window.open('_preview.html?t=' + Date.now(), 'motivate_preview');
            setStatus('Preview opened in its own tab');
        }).catch(function (err) {
            setStatus(err.message || 'Preview failed', true);
        }).finally(function () { setBusy(false); });
    }

    function save() {
        const spec = getSpec();
        const k = parseInt(spec.number, 10);
        const editing = mode() === 'edit';
        let question = null;
        if (editing) {
            question = 'Save changes to page ' + k + ' - ' + pages[k - 1].label.toUpperCase() + '?';
            if (spec.name.trim() !== pages[k - 1].label) {
                question += '\n\nThe page is renamed "' + spec.name.trim() + '" (file, menu and home box).';
            }
        } else if (k >= 1 && k <= last) {
            question = 'Insert "' + spec.name.trim() + '" as page ' + k + '?\n\n' +
                'Pages ' + k + '-' + last + ' will be renumbered ' + (k + 1) + '-' + (last + 1) + '.';
        }
        if (question && !confirm(question + '\nA backup of the site is saved first.')) return;
        setBusy(true);
        setStatus((editing ? 'Saving page ' : 'Creating page ') + k + '...');
        post(editing ? 'update' : 'create', spec).then(function (res) {
            if (!res.ok) throw new Error(res.error);
            if (!editing) clearDraft();
            dirty = false;
            setStatus((editing ? 'Saved ' : 'Created ') + res.file);
            location.href = res.file;
        }).catch(function (err) {
            setStatus(err.message || 'Save failed', true);
            setBusy(false);
        });
    }

    // ---------- Modes ----------
    function startNew() {
        loadedNumber = null;
        const draft = loadDraft();
        setSpec(draft ? Object.assign(draft, { number: cameFrom() }) : { number: cameFrom(), lines: [] });
        setStatus('');
    }

    function startEdit(k) {
        loadedNumber = null;
        setSpec({ number: k, lines: [] });
        setStatus('');
        if (online) loadPage(k);
    }

    form.addEventListener('change', function (e) {
        if (e.target.name === 'mode') {
            if (dirty && !confirm('Switch mode and leave the current form?')) {
                form.querySelector('input[value="' + (mode() === 'edit' ? 'new' : 'edit') + '"]').checked = true;
                return;
            }
            if (mode() === 'edit') startEdit(Math.min(Math.max(cameFrom() - 1, 1), last));
            else startNew();
            return;
        }
        if (e.target.id === 'pageNumber' && mode() === 'edit') {
            refresh();
            return;
        }
        changed();
    });
    form.addEventListener('input', function (e) {
        if (e.target.id === 'pageNumber') refresh();
        else changed();
    });
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    $('pageNumber').addEventListener('keydown', function (e) {
        if (e.key === 'Enter' && mode() === 'edit') loadPage(parseInt(this.value, 10));
    });
    $('loadBtn').addEventListener('click', function () { loadPage(parseInt($('pageNumber').value, 10)); });
    $('previewBtn').addEventListener('click', preview);
    $('saveBtn').addEventListener('click', save);
    $('resetBtn').addEventListener('click', function () {
        if (mode() === 'edit') {
            if (loadedNumber !== null && confirm('Undo all changes and reload page ' + loadedNumber + '?')) {
                dirty = false;
                loadPage(loadedNumber);
            }
        } else if (confirm('Clear the form?')) {
            clearDraft();
            setSpec({ number: cameFrom(), lines: [] });
            setStatus('');
        }
    });
    $('exitBtn').addEventListener('click', function () {
        if (dirty && mode() === 'edit' && !confirm('Leave without saving?')) return;
        if (document.referrer && history.length > 1) history.back();
        else location.href = 'index.html';
    });

    // ---------- Start (builder.html?at=N = new page / builder.html?edit=N = edit page N) ----------
    if (!online) $('banner').classList.add('show');
    const editAt = parseInt(params.get('edit'), 10);
    if (editAt >= 1 && editAt <= last) {
        form.querySelector('input[value="edit"]').checked = true;
        startEdit(editAt);
    } else {
        startNew();
    }
    if (online) {
        fetch('/api/ping', { cache: 'no-store' }).catch(function () {
            $('banner').classList.add('show');
            setBusy(true);
        });
    }
    $('pageName').focus();
})();

